import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices } from '../src/reports.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { invoiceTotals } from '../src/invoices.js';

test('overdueInvoices finds overdue invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const r2 = issueInvoice(r1.value, []);

  // Check as of Oct 20 (due date is Oct 15, so overdue)
  const report = overdueInvoices([r2.value], '2026-10-20');
  assert.equal(report.ok, true);
  assert.equal(report.value.length, 1);
  assert.equal(report.value[0].number, r2.value.number);
  assert.equal(report.value[0].customerId, 'C-001');
  assert.equal(report.value[0].dueDate, '2026-10-15');
  assert.equal(report.value[0].daysOverdue, 5);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const r2 = issueInvoice(r1.value, []);

  // Due Oct 15, check as of Oct 25 (10 days overdue)
  const report = overdueInvoices([r2.value], '2026-10-25');
  assert.equal(report.ok, true);
  assert.equal(report.value[0].daysOverdue, 10);
});

test('overdueInvoices excludes not-yet-due invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const r2 = issueInvoice(r1.value, []);

  // Check as of Oct 14 (due date is Oct 15, not overdue yet)
  const report = overdueInvoices([r2.value], '2026-10-14');
  assert.equal(report.ok, true);
  assert.equal(report.value.length, 0);
});

test('overdueInvoices excludes invoices due on asOf date', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const r2 = issueInvoice(r1.value, []);

  // Check as of due date (Oct 15, not overdue)
  const report = overdueInvoices([r2.value], '2026-10-15');
  assert.equal(report.ok, true);
  assert.equal(report.value.length, 0);
});

test('overdueInvoices excludes draft invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const report = overdueInvoices([r1.value], '2026-10-20');
  assert.equal(report.ok, true);
  assert.equal(report.value.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const r2 = issueInvoice(r1.value, []);
  const { total } = invoiceTotals(r2.value);
  const r3 = recordPayment(r2.value, { amount: total, date: '2026-10-15' });

  const report = overdueInvoices([r3.value], '2026-10-20');
  assert.equal(report.ok, true);
  assert.equal(report.value.length, 0);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const r2 = issueInvoice(r1.value, []);
  const { total } = invoiceTotals(r2.value);
  const r3 = recordPayment(r2.value, { amount: Math.floor(total / 2), date: '2026-10-15' });

  const report = overdueInvoices([r3.value], '2026-10-20');
  assert.equal(report.ok, true);
  assert.equal(report.value.length, 1);
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-20',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const r2 = issueInvoice(r1.value, []);

  const r3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const r4 = issueInvoice(r3.value, ['INV-2026-0001']);

  // r2 due Sep 4, r4 due Oct 15, check as of Oct 25
  const report = overdueInvoices([r4.value, r2.value], '2026-10-25');
  assert.equal(report.ok, true);
  assert.equal(report.value.length, 2);
  // First should be r2 (21 days overdue), then r4 (10 days overdue)
  assert.equal(report.value[0].daysOverdue, 21);
  assert.equal(report.value[1].daysOverdue, 10);
});

test('overdueInvoices calculates due amounts', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const r2 = issueInvoice(r1.value, []);
  const { total } = invoiceTotals(r2.value);

  const report = overdueInvoices([r2.value], '2026-10-20');
  assert.equal(report.ok, true);
  assert.equal(report.value[0].due, total);
});

test('overdueInvoices calculates due amounts for partially paid invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const r2 = issueInvoice(r1.value, []);
  const { total } = invoiceTotals(r2.value);
  const paid = Math.floor(total / 2);
  const r3 = recordPayment(r2.value, { amount: paid, date: '2026-10-15' });

  const report = overdueInvoices([r3.value], '2026-10-20');
  assert.equal(report.ok, true);
  assert.equal(report.value[0].due, total - paid);
});

test('overdueInvoices shows DRAFT for invoices without number', () => {
  const invoice = {
    status: 'issued',
    customerId: 'C-001',
    dueDate: '2026-10-15',
    lines: [{ qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 0 }],
  };

  const report = overdueInvoices([invoice], '2026-10-20');
  assert.equal(report.ok, true);
  assert.equal(report.value[0].number, 'DRAFT');
});

test('overdueInvoices rejects invalid asOf date', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r1.value, []);

  const report = overdueInvoices([r2.value], '10-20-2026');
  assert.equal(report.ok, false);
  assert.equal(report.error, 'DATE_INVALID');
});

test('overdueInvoices handles empty invoice list', () => {
  const report = overdueInvoices([], '2026-10-20');
  assert.equal(report.ok, true);
  assert.equal(report.value.length, 0);
});

test('overdueInvoices with multiple customers', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const r2 = issueInvoice(r1.value, []);

  const r3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const r4 = issueInvoice(r3.value, ['INV-2026-0001']);

  const report = overdueInvoices([r2.value, r4.value], '2026-10-20');
  assert.equal(report.ok, true);
  assert.equal(report.value.length, 2);
  assert.equal(report.value[0].customerId, 'C-001');
  assert.equal(report.value[1].customerId, 'C-002');
});

test('overdueInvoices with various due dates', () => {
  // Create invoices with different due dates
  const inv1 = { status: 'issued', customerId: 'C-001', dueDate: '2026-10-01', number: 'INV-1', lines: [{ qty: 1, unitPrice: 1000, vatRate: 0, discountPercent: 0 }] };
  const inv2 = { status: 'issued', customerId: 'C-002', dueDate: '2026-10-10', number: 'INV-2', lines: [{ qty: 1, unitPrice: 1000, vatRate: 0, discountPercent: 0 }] };
  const inv3 = { status: 'issued', customerId: 'C-003', dueDate: '2026-10-20', number: 'INV-3', lines: [{ qty: 1, unitPrice: 1000, vatRate: 0, discountPercent: 0 }] };

  const report = overdueInvoices([inv1, inv2, inv3], '2026-10-25');
  assert.equal(report.ok, true);
  assert.equal(report.value.length, 2);
  // inv1 is 24 days overdue, inv2 is 15 days overdue, inv3 is not overdue
  assert.equal(report.value[0].daysOverdue, 24);
  assert.equal(report.value[1].daysOverdue, 15);
  assert.equal(report.value[0].number, 'INV-1');
  assert.equal(report.value[1].number, 'INV-2');
});

